package com.yuegang.zhihui.ai.security;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import com.yuegang.zhihui.common.core.BusinessException;import com.yuegang.zhihui.common.security.InternalUserContextSignature;import jakarta.servlet.http.HttpServletRequest;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;
class AiUserResolverTest{@Test void resolvesSignedUserAndEnforcesPermission(){byte[]key="01234567890123456789012345678901".getBytes();var r=mock(HttpServletRequest.class);when(r.getMethod()).thenReturn("GET");when(r.getRequestURI()).thenReturn("/api/v1/ai/x");when(r.getHeader("X-YGH-User-Id")).thenReturn("7");when(r.getHeader("X-YGH-Roles")).thenReturn("USER");when(r.getHeader("X-YGH-Permissions")).thenReturn("ai:read");when(r.getHeader("X-Trace-Id")).thenReturn("t");when(r.getHeader("X-Request-Id")).thenReturn("q");String ts=Long.toString(System.currentTimeMillis());when(r.getHeader("X-YGH-User-Context-Timestamp")).thenReturn(ts);var m=new InternalUserContextSignature.Metadata("7",List.of("USER"),List.of("ai:read"),"t","q","GET","/api/v1/ai/x",Instant.ofEpochMilli(Long.parseLong(ts)));when(r.getHeader("X-YGH-User-Context-Signature")).thenReturn(new InternalUserContextSignature(key,Clock.systemUTC(),Duration.ofSeconds(30)).sign(m));var resolver=new AiUserResolver(key);assertThat(resolver.resolve(r)).isEqualTo(7);assertThat(resolver.resolveContext(r).knowledgeVisibilities()).containsExactly("PUBLIC");assertThat(resolver.require(r,"ai:read")).isEqualTo(7);assertThatThrownBy(()->resolver.require(r,"ai:admin")).isInstanceOf(BusinessException.class);when(r.getHeader("X-YGH-User-Id")).thenReturn(null);assertThatThrownBy(()->resolver.resolve(r)).isInstanceOf(BusinessException.class);}}
